castSealed(caster: Actor, inst: SkillInstance): CastSealSpec | null {
    const seal = this.zone.castSeal;
    if (!seal) return null;
    return castSealShuts(seal, { world: this, caster, inst, seated: this.seatOf(caster) !== undefined })
      ? seal : null;
  }

castReqRefusal(caster: Actor, inst: SkillInstance): string | undefined {
    const seat = this.seatOf(caster);
    if (!seat || inst.devGift || !seat.meta.knownSkills.has(inst.def.id)) return undefined;
    if (caster.activeAuras.has(inst.def.id) || caster.strobes.has(inst.def.id)) return undefined;
    return this.reqShortfall(inst.def.id, seat);
  }

skillUsable(a: Actor, inst: SkillInstance): boolean {
    const def = inst.def;
    // Trigger-socketed skills are never hand-castable: the slot greys and
    // the key becomes the arm/disarm latch (the border glow shows state).
    if (instanceTrigger(inst)) return false;
    // THE CAST SEAL greys the slot: the press would refuse, so the bar says so first.
    if (this.castSealed(a, inst)) return false;
    if (def.pool && !a.venting.has(def.pool.id)
      && (a.pools.get(def.pool.id) ?? 0) < (def.pool.min ?? 1)) return false;
    // Unmet PREREQUISITE gates grey the slot ("not ready").
    if (!a.gatesMet(inst)) return false;
    // Any hard charge economy greys until the bank can pay — an innate
    // cost (an empty flask fount, a chargeless Galvanic Reserve) exactly
    // as a socketed SPENDER graft (Embargo). Mirrors canUse: the press
    // would refuse, so the bar must say so first.
    {
      const cc = instanceChargeCost(inst);
      if (cc && !cc.optional) {
        const have = a.charges.get(cc.charge) ?? 0;
        const need = cc.amount === 'all' ? (cc.minimum ?? 1) : Math.max(cc.amount, cc.minimum ?? 0);
        if (have < need) return false;
      }
    }
    // Corpse targeting is excluded: its resolution has side effects
    // (Sacrificial Rites) — never run it from a render poll.
    const tspec = instanceTargeting(inst);
    if (tspec?.requiresStatus && tspec.target !== 'corpse') {
      return this.resolveTargeting(a, inst, a.aimPos ?? a.pos) !== null;
    }
    return true;
  }

pressUsable(caster: Actor, inst: SkillInstance): boolean {
    if (this.castSealed(caster, inst)) return false; // THE CAST SEAL — the brain never presses a sealed cast
    // A mimic slot presses as its selection — empty bank, dead button.
    if (inst.def.mimic) {
      const sel = mimicSelected(caster, this.time);
      if (!sel || !SKILLS[sel.sid]) return false;
      const minted = this.mintMetaInstance(caster, inst, sel.sid);
      minted.sockets = inst.sockets;
      minted.extraMods = mimicPowerMods(inst.def.mimic);
      return caster.canUse(minted);
    }
    // A queued chain step is judged as the step it would cast (the face
    // the bar shows) — an unaffordable finisher greys the slot honestly.
    const step = this.comboQueuedStep(caster, inst);
    if (step) return caster.canUse(step);
    const conv = instanceConvert(inst);
    if (conv && SKILLS[conv.skillId]
      && convertRuleHolds(conv.when, caster, inst, this)) {
      const minted = this.mintMetaInstance(caster, inst, conv.skillId);
      minted.sockets = inst.sockets; // same sharing rule as the press itself
      return caster.canUse(minted);
    }
    return caster.canUse(inst);
  }

slotFaceOf(caster: Actor, inst: SkillInstance): SkillDef {
    // A mimic slot wears the SELECTED captured art's face (the source
    // monster's chip rides the build flap — engine/mimic.ts).
    if (inst.def.mimic) {
      const sel = mimicSelected(caster, this.time);
      if (sel && SKILLS[sel.sid]) return SKILLS[sel.sid];
    }
    // THE HONEST CHAIN FACE (2026-09-11): while a combo chain's window
    // holds, the slot IS the step the next press will cast — Trisect
    // shows Bisect, One-Two shows the Cross Jab — the convert face's own
    // law. A lapsed window or a repeated step reads as the host itself.
    const step = this.comboQueuedStep(caster, inst);
    if (step) return step.def;
    const conv = instanceConvert(inst); // innate OR a munition graft's reload
    return conv && SKILLS[conv.skillId] && convertRuleHolds(conv.when, caster, inst, this)
      ? SKILLS[conv.skillId]
      : inst.def;
  }

comboQueuedStep(caster: Actor, inst: SkillInstance): SkillInstance | null {
    const chain = inst.def.comboChain;
    if (!chain?.skills.length) return null;
    const st = this.comboCursorOf(caster, inst);
    if (st.comboAt === undefined) return null;
    if (this.time - st.comboAt > chain.window) return null;
    return this.comboStepOf(caster, inst, st.comboIdx ?? 0);
  }

comboCursorOf(caster: Actor, inst: SkillInstance): ComboCursor {
    if (!caster.construct || caster.skills.includes(inst)) return (inst.state ??= {});
    let m = this.comboCursors.get(caster);
    if (!m) { m = new Map(); this.comboCursors.set(caster, m); }
    let c = m.get(inst.def.id);
    if (!c) { c = {}; m.set(inst.def.id, c); }
    return c;
  }

comboStepOf(caster: Actor, inst: SkillInstance, idx: number): SkillInstance | null {
    const chain = inst.def.comboChain;
    if (!chain || idx <= 0 || idx > chain.skills.length) return null;
    const sid = chain.skills[idx - 1];
    if (sid === inst.def.id || !SKILLS[sid]) return null;
    const key = inst.def.id + ':combo' + idx;
    const level = inst.level + Math.floor(inst.bonusLevels ?? 0);
    let step = caster.metaInsts.get(key);
    if (!step || step.def.id !== sid || step.level !== level) {
      step = makeSkillInstance(SKILLS[sid], level);
      step.hostSkillId = inst.def.id;
      step.chainOf = inst.def.id; // THE BEAT MARK — the ring records the host's beat
      caster.metaInsts.set(key, step);
    }
    step.sockets = inst.sockets; // live references — re-socketing propagates
    step.grafts = inst.grafts;
    step.comboTreeMods = instanceTreeMods(inst);
    return step;
  }

private mintMetaInstance(caster: Actor, host: SkillInstance, skillId: string): SkillInstance {
    const key = host.def.id + ':' + skillId;
    let inst = caster.metaInsts.get(key);
    const relocateConstruct = SKILLS[skillId].effects.some(fx => fx.type === 'relocateConstruct');
    if (!inst || inst.level !== effectiveSkillLevel(host)
      || (relocateConstruct && this.relocationHosts.get(inst) !== host)) {
      inst = makeSkillInstance(SKILLS[skillId], effectiveSkillLevel(host));
      // minionCombat: a command's meta inherits its whole-court scope.
      // Summon-hosted meta payloads still name their own roster anchor.
      inst.hostSkillId = host.def.effects.some(e => e.type === 'commandMinions')
        ? undefined : host.def.id;
      caster.metaInsts.set(key, inst);
      if (relocateConstruct) this.relocationHosts.set(inst, host);
    }
    return inst;
  }
